export default async function step({ payload, channels, ack, resolution, channelId }, ctx) {
  if (
    !payload ||
    typeof payload.id !== "string" ||
    !payload.id ||
    typeof payload.name !== "string" ||
    !payload.data ||
    typeof payload.data !== "object"
  )
    throw Error("Invalid Webflow submission");
  const key = "webflow-discord:" + payload.id,
    identity = JSON.stringify(payload);
  let s = await ctx.state.get(key);
  if (!s) {
    let name = payload.name.toLowerCase().trim().replace(/\s+/g, "-");
    if (!/^[\p{L}\p{N}_-]{1,100}$/u.test(name))
      throw Error("Form name cannot be a Discord channel");
    let matches = channels.filter((c) => c.name === name && c.type === 0);
    if (matches.length > 1) throw Error("Ambiguous channel");
    s = {
      identity,
      name,
      channel: matches[0]?.id ?? "",
      phase: matches.length ? "send-ready" : "create-ready",
    };
  }
  if (s.identity !== identity) throw Error("Submission ID reused with different data");
  if (s.phase.endsWith("-pending")) {
    if (ack !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect " + s.phase + " " + key);
    let p = s.phase.slice(0, -8);
    if (resolution === "absent") s.phase = p + "-ready";
    else if (p === "create") {
      if (!channelId) throw Error("Provide channel ID");
      s.channel = channelId;
      s.phase = "notice-ready";
    } else s.phase = p === "notice" ? "send-ready" : "done";
  }
  let action = s.phase.endsWith("-ready") ? s.phase.slice(0, -6) : s.phase;
  let content =
    "New form submission:\n" +
    Object.entries(payload.data)
      .map(([k, v]) => "**" + k + "**: " + (typeof v === "string" ? v : JSON.stringify(v)))
      .join("\n");
  if (content.length > 2000) throw Error("Submission exceeds Discord message limit");
  if (["create", "notice", "send"].includes(action)) s.phase = action + "-pending";
  await ctx.state.set(key, s);
  return {
    key,
    action,
    name: s.name,
    channel: s.channel,
    content,
    notice: "A new channel was created <#" + s.channel + ">",
  };
}

