export default async function confirm({ key, action, result }, ctx) {
  let id = result?.id,
    channel = result?.channel_id;
  let s = await ctx.state.get(key);
  if (s?.phase !== action + "-pending" || !id) throw Error("Inspect Discord result");
  if (action === "create") {
    s.channel = id;
    s.phase = "notice-ready";
  } else if (action === "notice") {
    if (!channel) throw Error("Missing notice channel");
    s.phase = "send-ready";
  } else if (action === "send") {
    if (channel !== s.channel) throw Error("Wrong Discord channel");
    s.phase = "done";
  } else throw Error("Invalid action");
  await ctx.state.set(key, s);
  return { ok: true };
}

